      lead: c => `നന്ദി ${c.hon}! കഴിഞ്ഞ തവണ ${c.days} ദിവസം മുമ്പ് ${c.lines} എടുത്തിരുന്നു. ഇത്തവണ എത്ര അയക്കണം?`,
      leadBrand: c => `ശരി ${c.hon}. ${c.brand}-ന് കഴിഞ്ഞ തവണ ${c.lines} എടുത്തിരുന്നു. ഇത്തവണ എത്ര വേണം?`,
      added: c => `ശരി, ${c.items} note ചെയ്തു. വേറെ എന്തെങ്കിലും വേണോ?`,
      updated: c => `ശരി, ${c.item} ഇപ്പോൾ ${c.qty} pieces. വേറെ എന്തെങ്കിലും?`,
