      askQty: c => `${c.item} എത്ര pieces അയക്കണം?${c.last ? ` കഴിഞ്ഞ തവണ ${c.last} എടുത്തിരുന്നു.` : ''}`,
      askBox: c => `${c.n} box-ൽ എത്ര pieces ഉണ്ടാകും? Billing piece കണക്കിലാണ്, ${c.item}-ന്റെ box size എനിക്ക് ഉറപ്പില്ല, അതുകൊണ്ട് pieces എണ്ണം പറയൂ.`,
