      objection: c => `മനസ്സിലാകുന്നു. ${c.item ? c.item + '-ൽ നിങ്ങളുടെ margin ഒരു piece-ന് ' + c.margin + '. ' : ''}Rate കുറയ്ക്കാൻ കഴിയില്ല, പക്ഷേ ഇത്തവണ കുറച്ച് quantity എടുക്കാം${c.lower ? ', ഉദാഹരണത്തിന് ' + c.lower + ' pieces' : ''}. എത്ര അയക്കണം?`,
