      stockNo: c => `${c.item} ഇപ്പോൾ നിങ്ങളുടെ distributor-ന്റെ അടുത്ത് stock ഇല്ല.${c.alt ? ' ' + c.alt + ' ഉണ്ട്.' : ''}`,
      terms: () => `Delivery-യും payment-ഉം നിങ്ങളുടെ distributor-ന്റെ സാധാരണ schedule, terms അനുസരിച്ചാണ്. വേറെ തീയതിയോ credit-ഓ ഉറപ്പ് തരാൻ എനിക്ക് കഴിയില്ല; വേണമെങ്കിൽ sales officer-മായി ബന്ധിപ്പിക്കാം.`,
      whoAreYou: () => `അതെ, ഞാൻ Marico-യുടെ AI sales assistant ആണ്, നിങ്ങളുടെ order എടുക്കാൻ വിളിച്ചതാണ്. വേണമെങ്കിൽ sales representative-ൽ നിന്ന് call ഏർപ്പാടാക്കാം.`,
      cancelled: () => `ശരി, order cancel ചെയ്തു; ഒന്നും അയക്കില്ല. നന്ദി!`,
