      askQty: c => `${c.item} কত pieces পাঠাব?${c.last ? ` গতবার ${c.last} নিয়েছিলেন।` : ''}`,
      askBox: c => `${c.n} box-এ কত pieces থাকবে? Billing piece হিসেবে হয়, আর ${c.item}-এর box size আমার কাছে নিশ্চিত নেই, তাই pieces-এর সংখ্যা বলুন।`,
